function depthFirstSearch(graph, startNode) {
  // Keep track of visited nodes
  const visited = {};
  // Initialize output array
  const result = [];

  // Define the recursive DFS function
  function dfs(node) {
    // Mark node as visited
    visited[node] = true;
    // Add node to output array
    result.push(node);
    // Visit all the neighbors of this node
    for (const neighbor of graph[node]) {
      // If neighbor hasn't been visited, visit it
      if (!visited[neighbor]) {
        dfs(neighbor);
      }
    }
  }

  // Perform the initial DFS with the starting node
  dfs(startNode);

  // Return the output array
  return result;
}
```

