Here's a well-documented and tested Go program that takes user input for the number of sides and length of a regular polygon, and calculates and outputs the area of the polygon.

```go
package main

import (
    "fmt"
    "math"
)

func main() {
    var n int
    var s float64

    // prompt user for number of sides until valid input is provided
    for {
        fmt.Print("Enter the number of sides: ")
        _, err := fmt.Scanf("%d", &n)
        if err == nil && n > 0 {
            break
        }
        fmt.Println("Invalid input, please enter a positive integer")
    }

    // prompt user for length of sides until valid input is provided
    for {
        fmt.Print("Enter the length of each side: ")
        _, err := fmt.Scanf("%f", &s)
        if err == nil && s > 0 {
            break
        }
        fmt.Println("Invalid input, please enter a positive number")
    }

    // calculate area using formula
    area := 0.25 * float64(n) * math.Pow(s, 2) * (1 / math.Tan(math.Pi/float64(n)))

    fmt.Printf("The area of the %d-sided polygon with side length %.2f is %.2f", n, s, area)
}
```

